Local Ltac dof_finish c' E' g' :=
  apply evt_done; unfold dof_post;
  do 16 eexists; exists c', E', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

Local Ltac forget_as H n :=
  let j := fresh "jk" in let B := fresh "BL" in
  destruct (rw_cells_forget _ _ _ _ H) as [j B]; cbn [cells_size csize Nat.add OptItCells OptU64Cells TokItCells map length] in B; clear H;
  try change (cells_size _) with n in B; rename B into H.

Local Ltac call_oincr A lst it vq vl err SP pad7 sbs lo ALSP :=
  let S := fresh "OI" in
  pose proof optit_incr_spec as S;
  unfold optit_incr_stmt, optit_incr_post, SZ_TOKIT, TOKIT_STACK, P_OPT_TOKEN_LIST_INCR in S; unfold wz in S;
  callZ (S A lst it vq vl err SP pad7 sbs (@nil cell) lo);
  [ fast_assumption | fast_assumption | fast_assumption | lia | lia | lia | cbn [cells_size csize Nat.add length]; lia
  | rewrite ?unsigned_lit by lia; fast_assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; lia
  | intros; lia | lia | apply al8_of_sp16; [exact ALSP | reflexivity] | fast_assumption | clear S ].

Local Ltac name_after sp off N vp :=
  lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + off) _ |- _ => rename H into N end;
  try match goal with H : bytes_at _ _ vp _, H' : bytes_at _ _ vp _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ vp _ |- _ => try rename H into WIN end;
  try match goal with H : mem_inv _ _, H' : mem_inv _ _ |- _ => clear H' end;
  lazymatch goal with H : mem_inv _ _ |- _ => try rename H into MI end.

