Local Ltac take_arm L :=
  let A := fresh "ARM" in
  pose proof L as A; unfold dof_arm_stmt in A; unfold wz in A;
  eapply A; [ exact I | | fast_eassumption | fast_eassumption | fast_eassumption | fast_eassumption ];
  unfold dof_ctx, dof_sv; unfold wz; repeat match goal with |- _ /\ _ => split end; fast_eassumption.

